const s=JSON.parse(JSON.stringify($json.state||$json));
s.settings={...s.settings,telegram_chat_id:'5731599300'};
s.telegram_chat_id='5731599300';
const safeName=String(s.article?.slug||'article').replace(/[^a-zA-Z0-9_-]/g,'-').replace(/-+/g,'-').slice(0,80)||'article';
const escapeHtml=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const binary={...($binary||{})};
const imgs=Array.isArray(s.images)?s.images:[];
if(!binary.article){
 let body=String(s.article?.content_html||'');
 for(const im of imgs.filter(x=>x.role!=='featured')){
  const marker='<!-- ARTICLE_IMAGE_'+Number(im.index)+' -->';
  const figure='<figure><img width="1200" height="630" alt="'+escapeHtml(im.alt_text)+'" src="data:image/webp;base64,'+im.base64+'"></figure>';
  body=body.replace(marker,figure);
 }
 const featured=imgs.find(x=>x.role==='featured');
 const featureFigure=featured?'<figure><img width="1200" height="630" alt="'+escapeHtml(featured.alt_text)+'" src="data:image/webp;base64,'+featured.base64+'"></figure>':'';
 const html='<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+escapeHtml(s.article?.title)+'</title><style>body{max-width:900px;margin:40px auto;padding:20px;font-family:Arial;line-height:1.9}img{max-width:100%;height:auto}</style><h1>'+escapeHtml(s.article?.title)+'</h1>'+featureFigure+body+'</html>';
 binary.article={data:Buffer.from(html,'utf8').toString('base64'),mimeType:'text/html',fileName:safeName+'.html'};
}
if(!binary.image){
 const featured=imgs.find(x=>x.role==='featured');
 const imageBase64=featured?.base64||s.image_base64;
 if(imageBase64)binary.image={data:imageBase64,mimeType:'image/webp',fileName:featured?.file_name||s.image?.file_name||safeName+'-featured.webp'};
}
return [{json:s,binary,pairedItem:{item:0}}];

const sha=x=>require('crypto').createHash('sha256').update(String(x),'utf8').digest('hex');
const parse=v=>{if(v&&typeof v==='object')return v;return JSON.parse(String(v||'').trim().replace(/^\x60\x60\x60(?:json)?\s*/,'').replace(/\s*\x60\x60\x60$/,''));};
const plain=x=>String(x||'').replace(/<[^>]*>/g,' ').replace(/&[^;]+;/g,' ').replace(/\s+/g,' ').trim();

function articleSections(html){
 const hs=[...html.matchAll(/<h2\b[^>]*>[\s\S]*?<\/h2>/gi)];
 return hs.map((m,i)=>{
  const start=m.index+m[0].length,end=i+1<hs.length?hs[i+1].index:html.length;
  const raw=html.slice(start,end),tail=(raw.match(/(?:\s|<!--\s*ARTICLE_IMAGE_[123]\s*-->)*$/)||[''])[0];
  return {id:'section_'+i,heading:m[0].replace(/<[^>]*>/g,'').trim(),start,end:end-tail.length,body_html:raw.slice(0,raw.length-tail.length)};
 });
}

return $input.all().map((item,i)=>{
 const s=item.json,sections=articleSections(String(s.article?.content_html||''));

 s.human_approval_required=true;
 s.review_article_hash=sha(JSON.stringify([s.article.title,s.article.content_html,s.article.seo_title,s.article.meta_description,s.article.slug,s.article.keyword,s.article.category_id??null,s.article.existing_tag_ids??[]]));
 s.review_article_version=s.article_version?.version||('revision-'+String(s.revision||0));
 const report={completion_review:s.completion_review,writing_plan:s.writing_plan,writing_execution:s.writing_execution,title:s.article.title,article_hash:s.review_article_hash,article_version:s.review_article_version,review_token:s.review_token,style_brief:s.style_brief,style_review:s.style_review,human_editor:s.human_editor,legal_recheck:s.legal_recheck,legal_baseline_article:s.legal_baseline_article,current_article:s.article,notes:s.review_warning_text};
 s.editorial_report=report;

 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const labels={opening_specificity:'خصوصية الافتتاح',legal_clarity:'وضوح القانون',practical_depth:'العمق العملي',natural_flow:'سلاسة التدفق',non_repetition:'عدم التكرار',reader_usefulness:'فائدة القارئ',style_identity:'هوية الأسلوب'};
 const scoreRows=Object.entries(s.style_review?.dimensions||{}).map(([k,v])=>'<tr><td>'+esc(labels[k]||k)+'</td><td>'+esc(v.score??'غير متاح')+' / '+esc(v.max)+'</td><td>'+esc(v.evidence)+'</td><td>'+esc(v.fix)+'</td></tr>').join('');
 const diffs=[...(s.legal_recheck?.differences||[]),...(s.human_editor?.legal_review_needed||[])];
 const diffRows=diffs.map(d=>'<tr><td>'+esc(d.location||d.category)+'</td><td>'+esc(d.before)+'</td><td>'+esc(d.after)+'</td><td>'+esc(d.explanation||d.reason)+'</td></tr>').join('');
 const changeRows=(s.human_editor?.change_log||[]).map(d=>'<tr><td>'+esc(d.location)+'</td><td>'+esc(d.before)+'</td><td>'+esc(d.after)+'</td><td>'+esc(d.reason)+'</td></tr>').join('');
 const doc='<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><title>تقرير المراجعة</title><style>body{font-family:Arial;max-width:1100px;margin:32px auto;padding:20px;line-height:1.8;color:#172438}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccc;padding:8px;vertical-align:top}pre{white-space:pre-wrap;overflow-wrap:anywhere}.note{background:#fff4d4;padding:12px}</style><h1>'+esc(s.article.title)+'</h1><p>نسخة: '+esc(s.review_article_version)+'<br>Hash: '+esc(s.review_article_hash)+'</p><p class="note">الدرجات مؤشرات جودة تحريرية وليست إثباتًا لهوية الكاتب. الملاحظات القانونية لا تمنع مرور المقال؛ قرار الموافقة أو الرفض لك.</p><h2>تقييم الأسلوب: '+esc(s.style_review?.total??'غير متاح')+' / 100</h2><p>المطلوب 85 على الأقل وكل بُعد 60% على الأقل. النتيجة: '+esc(s.style_review?.decision)+'</p><table><tr><th>البعد</th><th>الدرجة</th><th>الدليل</th><th>التحسين</th></tr>'+scoreRows+'</table><h2>الفروق القانونية المحتملة</h2><p>'+esc(s.legal_recheck?.summary)+'</p><table><tr><th>الموضع</th><th>قبل</th><th>بعد</th><th>سبب المراجعة</th></tr>'+diffRows+'</table><pre>'+esc(JSON.stringify({uncertainties:s.legal_recheck?.uncertainties,number_changes:s.legal_recheck?.deterministic},null,2))+'</pre><h2>سجل التحرير</h2><table><tr><th>الموضع</th><th>قبل</th><th>بعد</th><th>السبب</th></tr>'+changeRows+'</table><h2>تنبيهات المراجعة</h2><pre>'+esc(s.review_warning_text)+'</pre><details><summary>Style Brief والمراجع المعتمدة</summary><pre>'+esc(JSON.stringify(s.style_brief,null,2))+'</pre></details><details><summary>النسخة قبل التحرير</summary><pre>'+esc(s.legal_baseline_article?.content_html)+'</pre></details><details><summary>النسخة الحالية</summary><pre>'+esc(s.article.content_html)+'</pre></details></html>';
 item.binary={...(item.binary||{}),editorial_report:{data:Buffer.from(doc,'utf8').toString('base64'),mimeType:'text/html',fileName:'editorial-review-'+String(s.topic?.topic_id||'article').replace(/[^a-zA-Z0-9_-]/g,'_')+'.html'}};

s.review_section_options=['تحديد تلقائي من الملاحظات',...sections.map(x=>x.id+' | '+x.heading),'العنوان الرئيسي فقط','عنوان SEO فقط','وصف الميتا فقط','كل نص المقال'];
 return {json:s,...(item.binary?{binary:item.binary}:{}),pairedItem:{item:i}};
});

const sha=x=>require('crypto').createHash('sha256').update(String(x),'utf8').digest('hex');
const parse=v=>{if(v&&typeof v==='object')return v;return JSON.parse(String(v||'').trim().replace(/^\x60\x60\x60(?:json)?\s*/,'').replace(/\s*\x60\x60\x60$/,''));};
const plain=x=>String(x||'').replace(/<[^>]*>/g,' ').replace(/&[^;]+;/g,' ').replace(/\s+/g,' ').trim();

 const s=JSON.parse(JSON.stringify($('Review Request Context').item.json)),d=$json.data||{},expired=s.review_deadline&&Date.parse(s.review_deadline)<=Date.now();
 if(!d['القرار']&&expired){s.decision='timeout';s.reason='انتهت مهلة المراجعة دون قرار';}
 else{
  if(expired)throw new Error('Expired review token');
  if(d.review_token!==s.review_token||d.article_hash!==s.review_article_hash)throw new Error('Stale or mismatched article revision');
  if(!String(d['اسم المراجع']||'').trim())throw new Error('Reviewer name required');
  s.decision=({'موافقة':'approve','تعديل':'revise','رفض':'reject'})[d['القرار']];if(!s.decision)throw new Error('Unknown decision');
  s.feedback=String(d['ملاحظات التعديل']||'').trim();s.revision_scope=String(d['نطاق التعديل']||'تعديل النص فقط').trim()==='تعديل النص والصور'?'text_and_images':'text_only';
  s.revision_target=String(d['القسم المطلوب تعديله']||'تحديد تلقائي من الملاحظات').trim();
  if(s.decision==='revise'&&!s.feedback){s.decision='missing_feedback';s.reason='اكتب التعديلات المطلوبة.';}
 }
 const at=new Date().toISOString();
 s.approval_audit={audit_id:sha([s.review_token,s.review_article_hash,s.decision,at].join('|')),review_token:s.review_token,article_hash:s.review_article_hash,article_version:s.review_article_version,topic_id:String(s.topic?.topic_id||''),reviewer_name:String(d['اسم المراجع']||'').trim()||'no_response',identity_source:'self_reported_review_form',identity_verified:false,decided_at:at,decision:s.decision,human_approval_required:true,style_score:typeof s.style_review?.total==='number'&&Number.isFinite(s.style_review.total)?s.style_review.total:null,change_summary:JSON.stringify(s.human_editor?.change_log||[]),report_json:JSON.stringify({...s.editorial_report,feedback:s.feedback||'',decision:s.decision})};
 if(s.decision==='approve'){s.approved_article_hash=sha(JSON.stringify([s.article.title,s.article.content_html,s.article.seo_title,s.article.meta_description,s.article.slug,s.article.keyword,s.article.category_id??null,s.article.existing_tag_ids??[]]));s.approved_image_hash=sha(JSON.stringify(s.images||[]));}
 return [{json:s}];
